#include "units.hpp"
bool boxes_needed(long long items, long long capacity, long long& result) {
    if (items < 0 || items > 1000000 || capacity < 1 || capacity > 1000) {
        return false;
    }
    result = items / capacity + (items % capacity != 0);
    return true;
}

